import generated from "./loadgen-spend.generated.json";

/**
 * What our own testing has cost (#500), generated by `scripts/loadgen-spend.mjs`.
 *
 * The number a sceptical reader wants is not how much moved — every transfer went to our own payee and came back. It is what the round
 * trip burned in gas, against a cap we state ourselves. Publishing the headroom is the point: a project with $50 of headroom and $0.15
 * spent is a project that is not buying attention.
 */
export interface LoadgenSpend {
  settlements: number;
  usdcMoved: string;
  usdcReturnedToOurselves: string;
  cappedAt: { usd: number; windowDays: number };
  gas: {
    unitsPerSettlement: number;
    gasPriceGweiP90: number;
    ethUsd: number;
    perSettlementUsd: number;
    burnedUsd: number;
    percentOfCap: number;
    headroomUsd: number;
  };
  provenance: string;
}

export const SPEND = generated as LoadgenSpend;
